import unittest, io

class MathUtils:
    @staticmethod
    def divide(a, b):
        if b == 0:
            raise ValueError("Cannot divide by zero")
        return a / b

class TestMathUtils(unittest.TestCase):
    def test_divide_normal(self):
        self.assertEqual(MathUtils.divide(10, 2), 5.0)
    def test_divide_negative(self):
        self.assertAlmostEqual(MathUtils.divide(-9, 3), -3.0)
    def test_divide_by_zero(self):
        with self.assertRaises(ValueError):
            MathUtils.divide(5, 0)

suite  = unittest.TestLoader().loadTestsFromTestCase(TestMathUtils)
result = unittest.TextTestRunner(verbosity=0,
                                  stream=io.StringIO()).run(suite)
print(f"Ran {result.testsRun} tests")
print("OK" if result.wasSuccessful() else
      f"FAILED ({len(result.failures)} failures)")
